"""Generates the CLEANUP revision from the qualified WINDOWED revision, by exact-match patches (each asserted to match exactly once), so the whole difference is this file.
Nothing frozen or qualified is touched: the windowed directory is only read, and its hashes are checked against the pins of its own qualification first.
What the revision adds: after a payment is SETTLED (the pool transition reconciled from validated history), the relay closes the two accounts it created for that request —
the verifier receipt (verifier opcode 2) and the proof buffer (buffer opcode 3) — so their rent returns to the sponsor. Each close is an ordinary durable, funded attempt of the
publication journal; nothing else about publication changes. usage: make_revision.py (once; refuses to overwrite)"""
import difflib,hashlib,json,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;WORK=HERE.parent
W=WORK/'solana-relay-windowed-v1'
POLICY=WORK/'solana-relay-performance-v1/candidate/publication-policy.mjs'
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
# 0. derive only from what was qualified
pins=json.loads((W/'evidence/checks-02/INPUTS.json').read_text())
for name in ('relay-publication.mjs','publication-sender.mjs','relay-task.mjs','harness.mjs','checks.mjs','crash-child.mjs'):
    key=str(W/name)
    assert key in pins and sha(W/name)==pins[key],'the windowed revision changed since its checks: '+name
assert sha(POLICY)==json.loads((W/'evidence/checks-02/INPUTS.json').read_text()).get(str(POLICY),sha(POLICY))
out=lambda n:HERE/n
for n in ('cleanup-policy.mjs','relay-publication.mjs','publication-sender.mjs','relay-task.mjs','harness.mjs','checks.mjs','crash-child.mjs'):
    assert not out(n).exists(),'refusing to overwrite '+n
diffs=HERE/'evidence/diffs-01';diffs.mkdir(parents=True)

def patch(text,pairs,label):
    for old,new in pairs:
        assert text.count(old)==1,(label,old[:80],text.count(old))
        text=text.replace(old,new)
    return text
def write(name,source,pairs,header=None):
    original=source.read_text()
    new=patch(original,pairs,name)
    if header:new=header+new
    out(name).write_text(new)
    (diffs/(name+'.diff')).write_text(''.join(difflib.unified_diff(original.splitlines(True),new.splitlines(True),str(source.relative_to(WORK)),'solana-relay-cleanup-v1/'+name)))

# 1. the policy: two more steps, both fixed instructions on the request's own accounts
write('cleanup-policy.mjs',POLICY,[
 ("import {requireState as require,integer} from './checkpoint.mjs';\nimport {checkedTransport,parsePaymentWire} from './payment-wire.mjs';\nimport {b58,un58,concat,u32,u64,sha256,decodeTransaction,instructionEqual} from './solana-transaction.mjs';\nimport {bufferPlan,inspectBuffer} from './proof-buffer.mjs';\nimport {checkWire,readProgress,nextStep,assertForward} from './proof-progress.mjs';",
  "import {requireState as require,integer} from '../solana-relay-performance-v1/candidate/checkpoint.mjs';\nimport {checkedTransport,parsePaymentWire} from '../solana-relay-performance-v1/candidate/payment-wire.mjs';\nimport {b58,un58,concat,u32,u64,sha256,decodeTransaction,instructionEqual} from '../solana-relay-performance-v1/candidate/solana-transaction.mjs';\nimport {bufferPlan,inspectBuffer} from '../solana-relay-performance-v1/candidate/proof-buffer.mjs';\nimport {checkWire,readProgress,nextStep,assertForward} from '../solana-relay-performance-v1/candidate/proof-progress.mjs';"),
 ("      if(name==='buffer-seal') {require(work===0);instructions=[this.#bufferIx(Uint8Array.of(2))];}\n",
  "      if(name==='buffer-seal') {require(work===0);instructions=[this.#bufferIx(Uint8Array.of(2))];}\n      // Cleanup: give the rent of the request's own two accounts back to the sponsor that paid it. Buffer opcode 3 and verifier opcode 2 each return the\n      // lamports only to the recorded authority, which must sign and be writable; nothing else is expressible here.\n      else if(name==='buffer-close') {require(work===0);instructions=[this.#bufferIx(Uint8Array.of(3))];}\n      else if(name==='receipt-close') {require(work===0);instructions=[this.#proofIx(Uint8Array.of(2))];}\n"),
 ("  seal() {return this.restore({name:'buffer-seal',rent:0,work:0});}\n",
  "  seal() {return this.restore({name:'buffer-seal',rent:0,work:0});}\n  bufferClose() {return this.restore({name:'buffer-close',rent:0,work:0});}\n  receiptClose() {return this.restore({name:'receipt-close',rent:0,work:0});}\n"),
],"// CLEANUP revision of ../solana-relay-performance-v1/candidate/publication-policy.mjs (frozen, untouched): adds the two close steps. Generated by make_revision.py.\n")

# 2. the journal: a `close` action (same record format, same version label; only two more descriptor names exist)
write('relay-publication.mjs',W/'relay-publication.mjs',[
 ("import {PublicationPolicy} from '../solana-relay-performance-v1/candidate/publication-policy.mjs';","import {PublicationPolicy} from './cleanup-policy.mjs';"),
 ("    else if(action.type==='verify'){exact(action,['type','receipt','work']);step=this.#policy.next(action.receipt,action.work);}\n",
  "    else if(action.type==='verify'){exact(action,['type','receipt','work']);step=this.#policy.next(action.receipt,action.work);}\n    else if(action.type==='close'){exact(action,['type','which']);require(action.which==='receipt'||action.which==='buffer','Unknown cleanup target.');\n      step=action.which==='receipt'?this.#policy.receiptClose():this.#policy.bufferClose();}\n"),
],"// CLEANUP revision of ../solana-relay-windowed-v1/relay-publication.mjs (qualified, untouched): adds the `close` action. Generated by make_revision.py.\n")

# 3. the sender: a cleanup phase that only the task can switch on, after settlement
write('publication-sender.mjs',W/'publication-sender.mjs',[
 ("  #closed=false;#busy=false;#id=null;#config=null;#slot=0;#receipt=null;#buffer=null;\n","  #closed=false;#busy=false;#id=null;#config=null;#slot=0;#receipt=null;#buffer=null;#cleanup=false;\n"),
 ("  requireSync(){this.#reset();}\n","  requireSync(){this.#reset();}\n  // Called by the task only once the pool transition has been reconciled from validated history. Irreversible for this sender instance.\n  beginCleanup(){this.#cleanup=true;}\n"),
 ("    const c=this.#config,stored=await this.#account(c.transport.source),proof=await this.#account(c.transport.receipt);\n    if(stored===null){require(proof===null,'Receipt exists without its proof source.');return this.#create('buffer',c.buffer_size);}\n",
  "    const c=this.#config,stored=await this.#account(c.transport.source),proof=await this.#account(c.transport.receipt);\n    if(this.#cleanup) {\n      // Receipt first, then the buffer. Before the buffer goes it must still hold exactly the proof we hold: those stored bytes are the audit evidence.\n      if(proof!==null)return {type:'close',which:'receipt'};\n      if(stored!==null){const view=await this.#bufferView(stored);require(view.sealed&&view.pending.length===0,'Cleanup found an incomplete proof buffer.');return {type:'close',which:'buffer'};}\n      return null;\n    }\n    if(stored===null){require(proof===null,'Receipt exists without its proof source.');return this.#create('buffer',c.buffer_size);}\n"),
 ("    const name=attempt.descriptor.name,c=this.#config;\n    const source=await this.#account(c.transport.source);if(source===null)return false;\n",
  "    const name=attempt.descriptor.name,c=this.#config;\n    // A close has taken effect when the account is gone.\n    if(name==='receipt-close')return (await this.#account(c.transport.receipt))===null;\n    if(name==='buffer-close')return (await this.#account(c.transport.source))===null;\n    const source=await this.#account(c.transport.source);if(source===null)return false;\n"),
 ("        const action=await this.#choice();this.#active();if(action===null)return {id,state:'verified',settled:false};\n",
  "        const action=await this.#choice();this.#active();if(action===null)return this.#cleanup?{id,state:'cleaned'}:{id,state:'verified',settled:false};\n"),
],"// CLEANUP revision of ../solana-relay-windowed-v1/publication-sender.mjs (qualified, untouched): adds the cleanup phase. Generated by make_revision.py.\n")

# 4. the task: after `settled`, run the cleanup phase before reporting the payment finished
write('relay-task.mjs',W/'relay-task.mjs',[
 ("  #context;#program;#pool;#validator;#slot=0;#history=null;#state='settling';#published=false;#closed=false;#busy=false;#signal;\n",
  "  #context;#program;#pool;#validator;#slot=0;#history=null;#state='settling';#published=false;#closed=false;#busy=false;#signal;\n  #cleanup=true;#cleaning=false;#cleaned=false;\n"),
 ("    funding,maxPublicationAttempts=12000,window=64,fetchImpl}){\n","    funding,maxPublicationAttempts=12000,window=64,cleanup=true,fetchImpl}){\n"),
 ("    require(Number.isSafeInteger(window)&&window>=1&&window<=MAX_WINDOW,'Invalid chunk window size.');\n","    require(Number.isSafeInteger(window)&&window>=1&&window<=MAX_WINDOW,'Invalid chunk window size.');\n    require(typeof cleanup==='boolean','Invalid cleanup option.');t.#cleanup=cleanup;\n"),
 ("isSettling:()=>t.#state==='settling'});","isSettling:()=>t.#state==='settling'||(t.#cleaning&&t.#state==='settled')});"),
 ("      if(['settled','conflicted'].includes(this.#state))return {id:this.id,state:this.#state,settled:this.#state==='settled'};\n",
  "      if(['settled','conflicted'].includes(this.#state)) {\n        // Only a payment the pool has settled is cleaned up (a conflicted request keeps its accounts until a person looks at it).\n        if(this.#state==='settled'&&this.#cleanup&&!this.#cleaned) {\n          this.#cleaning=true;this.#publisher.beginCleanup();\n          const result=await this.#publisher.step(this.#logicalId);this.#active();\n          if(result.state==='failed')throw Error('A cleanup transaction failed on the cluster.');\n          if(result.state!=='cleaned')return {...result,id:this.id,phase:'cleanup'};\n          this.#cleaned=true;\n        }\n        return {id:this.id,state:this.#state,settled:this.#state==='settled'};\n      }\n"),

 # found by full-06: the settlement sender reports `settled` inside its OWN step, and the supervisor stops stepping a request as soon as it is told `settled`; the cleanup block at the top
 # of step() was therefore never reached. Every step result now goes through routeStepResult, which holds `settled` back while the accounts are still open.
 ("export class LocalRelayTask {\n",
  "// The supervisor stops stepping a request the moment it is told `settled`. The settlement sender reports `settled` inside its own step (it reconciles by itself), so with cleanup on that\n"
  "// result must NOT reach the supervisor yet: the accounts are still open. This is the only place a step result becomes what the supervisor sees.\n"
  "export function routeStepResult(result,{id,state,cleanup,cleaned}) {\n"
  "  if(result.state==='settled'&&state==='settled'&&cleanup===true&&cleaned===false)return {id,state:'cleanup_pending',phase:'cleanup'};\n"
  "  return {...result,id};\n}\n"
  "export class LocalRelayTask {\n"),
 ("      this.#active();if(result.state==='verified')this.#published=true;\n      return {...result,id:this.id};\n",
  "      this.#active();if(result.state==='verified')this.#published=true;\n      return routeStepResult(result,{id:this.id,state:this.#state,cleanup:this.#cleanup,cleaned:this.#cleaned});\n"),
],"// CLEANUP revision of ../solana-relay-windowed-v1/relay-task.mjs (qualified, untouched): runs the cleanup phase after settlement. Generated by make_revision.py.\n")

# 5. the model cluster learns to hold a receipt and to close accounts
write('harness.mjs',W/'harness.mjs',[
 ("    this.accounts.set(source,{plan,data});\n  }\n","    this.accounts.set(source,{plan,data,lamports:21448444080,authority});\n  }\n  // The verifier's receipt for the request (owned by the verifier program; rent figure from the local runs).\n  createReceipt({receipt,authority,owner,lamports=2290000000}) {this.accounts.set(receipt,{kind:'receipt',owner,authority,lamports,data:Buffer.alloc(87000)});}\n  // The state after a payment: every chunk stored and the buffer sealed (what publication leaves behind), without replaying thousands of transactions.\n  fillBuffer({source,wire,plan}) {\n    const a=this.accounts.get(source);\n    for(let i=0;i<plan.count;i++) {\n      a.data[85+(i>>3)]|=1<<(i%8);Buffer.from(plan.leaves[i]).copy(a.data,plan.hashStart+32*i);\n      Buffer.from(wire.subarray(i*900,Math.min((i+1)*900,wire.length))).copy(a.data,plan.start+i*900);\n    }\n    a.data.writeUInt32LE(plan.count,44);a.data[80]=2;\n  }\n  closed=[];dropAllSends=false;#gone=new Map();\n  #close(key,a,done){this.accounts.delete(key);this.#gone.set(key,a);this.balance+=a.lamports;this.closed.push({key,lamports:a.lamports});return done(null);}\n"),
 ("    const a=this.accounts.get(pub);if(!a)return null;\n","    let a=this.accounts.get(pub);\n    if(!a&&this.staleReads>0&&this.#gone.has(pub)){this.staleReads--;a=this.#gone.get(pub);}   // a node that has not yet seen the close\n    if(!a)return null;\n"),
 ("    this.log.push({t:'send',sig:tx.signature,idx,tag});if(idx!==null)this.sigIdx.set(tx.signature,idx);\n","    this.log.push({t:'send',sig:tx.signature,idx,tag});if(idx!==null)this.sigIdx.set(tx.signature,idx);\n    if(this.dropAllSends)return tx.signature;\n"),
 ("    return {executable:false,owner:BUFFER,lamports:1,data:[Buffer.from(data).toString('base64'),'base64']};","    return {executable:false,owner:a.owner??BUFFER,lamports:a.lamports??1,data:[Buffer.from(data).toString('base64'),'base64']};"),
 ("    if(!a||ix.program.length!==32||b58(ix.program)!==BUFFER)return done({InstructionError:[1,'IncorrectProgramId']});\n",
  "    if(a?.kind==='receipt') {   // verifier opcode 2 closes the receipt, for the recorded authority only\n      if(b58(ix.program)!==a.owner||ix.data.length!==1||ix.data[0]!==2)return done({InstructionError:[1,'InvalidInstructionData']});\n      if(b58(tx.authority)!==a.authority)return done({InstructionError:[1,'MissingRequiredSignature']});\n      return this.#close(key,a,done);\n    }\n    if(!a||ix.program.length!==32||b58(ix.program)!==BUFFER)return done({InstructionError:[1,'IncorrectProgramId']});\n"),
 ("    const tag=ix.data[0],{plan}=a;\n","    const tag=ix.data[0],{plan}=a;\n    if(tag===3) {   // buffer opcode 3: close, lamports to the recorded owner\n      if(ix.data.length!==1)return done({InstructionError:[1,'InvalidInstructionData']});\n      return this.#close(key,a,done);\n    }\n"),
 ("  env.plan=PLANS[kind]??=await bufferPlan(wire);\n","  env.plan=PLANS[kind]??=await bufferPlan(wire);\n  // The state a settled payment leaves behind: a full, sealed buffer and the verifier's receipt.\n  env.arrangeSettled=()=>{chain.fillBuffer({source:env.transport.source,wire,plan:env.plan});chain.createReceipt({receipt:env.transport.receipt,authority:env.authority,owner:proofProgram});};\n"),
 # a restart must not conjure back an account that was closed: only a buffer that never existed is created here
 ("  if(!chain.accounts.has(env.transport.source))chain.createBuffer(","  if(!chain.accounts.has(env.transport.source)&&!chain.closed.some(c=>c.key===env.transport.source))chain.createBuffer("),
],"// CLEANUP revision of ../solana-relay-windowed-v1/harness.mjs: the model cluster also holds a verifier receipt and closes accounts. Generated by make_revision.py.\n")

# 6. unchanged qualified modules are re-exported under their old names, so the windowed regression checks run unmodified against this directory
for name in ('relay-repository.mjs','relay-funding.mjs','publication-adapter.mjs'):
    out(name).write_text("// Unchanged from the qualified windowed revision; re-exported so the same checks run against this directory.\nexport * from '../solana-relay-windowed-v1/%s';\n"%name)
# 7. the windowed checks, verbatim: they are the regression suite for everything the cleanup revision must not change
for name in ('checks.mjs','crash-child.mjs'):
    out(name).write_text((W/name).read_text())
print('generated:',sorted(p.name for p in HERE.iterdir() if p.is_file()))
